package com.example.myvillage.client.entity;

import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;

/** Bundled presentation configuration, generated by the sword owner. No gameplay decisions. */
public record FlyingSwordVisuals(float boost_fov, float fov_response, float boost_lean_degrees,
        float cruise_lean_degrees, float max_bank_degrees, int trail_interval_ticks, double trail_distance,
        int wind_interval_ticks, float wind_volume, float wind_pitch, float model_scale, float model_y_offset) {
    private static final FlyingSwordVisuals INSTANCE = load();
    public static FlyingSwordVisuals get() { return INSTANCE; }
    private static FlyingSwordVisuals load() {
        var stream = FlyingSwordVisuals.class.getResourceAsStream("/assets/myvillage/flying_sword/visuals.json");
        if (stream == null) throw new IllegalStateException("缺少御剑表现配置");
        try (var reader = new InputStreamReader(stream, StandardCharsets.UTF_8)) {
            return new Gson().fromJson(reader, FlyingSwordVisuals.class);
        } catch (java.io.IOException e) { throw new IllegalStateException("无法读取御剑表现配置", e); }
    }
}
